-- Isolated test model only; not an applied Supabase schema or assignment authority.
CREATE TABLE __SCHEMA__.drivers(id uuid PRIMARY KEY,user_id uuid UNIQUE NOT NULL,status text NOT NULL CHECK(status IN ('pending','approved','suspended','banned')));
CREATE TABLE __SCHEMA__.rides(id uuid PRIMARY KEY,user_id uuid NOT NULL,driver_id uuid REFERENCES __SCHEMA__.drivers(id),status text NOT NULL CHECK(status IN ('pending','scheduled','accepted','arrived','in_progress','completed','cancelled','expired')),expires_at timestamptz,assignment_id uuid,fare numeric(20,2));
-- offers.driver_id is an AUTH subject. expires_at is a proposed fixture field,
-- not evidence that production offers already has an expiry column.
CREATE TABLE __SCHEMA__.offers(id uuid PRIMARY KEY,ride_id uuid NOT NULL REFERENCES __SCHEMA__.rides(id),driver_id uuid NOT NULL,price numeric(20,2) NOT NULL,status text NOT NULL CHECK(status IN ('pending','accepted','rejected','cancelled','expired')),expires_at timestamptz NOT NULL,UNIQUE(id,ride_id));
CREATE TABLE __SCHEMA__.accepted_agreements(id uuid PRIMARY KEY,ride_id uuid UNIQUE NOT NULL REFERENCES __SCHEMA__.rides(id),driver_id uuid NOT NULL REFERENCES __SCHEMA__.drivers(id),offer_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),UNIQUE(id,ride_id,driver_id),FOREIGN KEY(offer_id,ride_id) REFERENCES __SCHEMA__.offers(id,ride_id));
ALTER TABLE __SCHEMA__.rides ADD FOREIGN KEY(assignment_id) REFERENCES __SCHEMA__.accepted_agreements(id);
CREATE TABLE __SCHEMA__.active_driver_reservations(driver_id uuid PRIMARY KEY,ride_id uuid UNIQUE NOT NULL,assignment_id uuid UNIQUE NOT NULL,FOREIGN KEY(assignment_id,ride_id,driver_id) REFERENCES __SCHEMA__.accepted_agreements(id,ride_id,driver_id));
CREATE TABLE __SCHEMA__.command_receipts(actor_id uuid NOT NULL,operation text NOT NULL,idempotency_key text NOT NULL,request_hash bytea NOT NULL CHECK(octet_length(request_hash)=32),assignment_id uuid REFERENCES __SCHEMA__.accepted_agreements(id),state text NOT NULL CHECK(state IN ('pending','committed')),result jsonb,PRIMARY KEY(actor_id,operation,idempotency_key),CHECK(state<>'committed' OR result IS NOT NULL));
